// Build step (optional for local use; run by CI and Cloudflare Pages):
//   node scripts/build.mjs          → updates sw.js precache list + version, _headers CSP, sitemap.xml
//   node scripts/build.mjs --check  → exits 1 if generated files are out of date (used in CI)
// The site itself needs no bundling: it is plain HTML/CSS/ES modules served from /public.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const PUB = path.join(ROOT, 'public');
const check = process.argv.includes('--check');
let stale = [];

const walk = (dir) => fs.readdirSync(dir, { withFileTypes: true }).flatMap((d) => (d.isDirectory() ? walk(path.join(dir, d.name)) : [path.join(dir, d.name)]));
const rel = (f) => path.relative(PUB, f).split(path.sep).join('/');
const SKIP = new Set(['sw.js', '_headers', '_redirects', 'ads.txt', 'robots.txt', 'sitemap.xml']);
const files = walk(PUB).map(rel).filter((f) => !SKIP.has(f) && !f.startsWith('.') && !f.endsWith('.map') && !f.startsWith('icons/og')).sort();

function write(file, content) {
  const p = path.join(PUB, file);
  const old = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null;
  if (old === content) return;
  if (check) stale.push(file); else { fs.writeFileSync(p, content); console.log('updated', file); }
}

// 1) service worker precache list + content version
const hash = crypto.createHash('sha256');
for (const f of files) { hash.update(f); hash.update(fs.readFileSync(path.join(PUB, f))); }
const version = hash.digest('hex').slice(0, 12);
const precache = ['./', ...files];
const sw = fs.readFileSync(path.join(PUB, 'sw.js'), 'utf8');
const block = `// BUILD-START (generated by scripts/build.mjs — do not edit by hand)\nconst VERSION = '${version}';\nconst PRECACHE = ${JSON.stringify(precache, null, 0).replace(/","/g, '", "')};\n// BUILD-END`;
write('sw.js', sw.replace(/\/\/ BUILD-START[\s\S]*?\/\/ BUILD-END/, block));

// 2) security headers — strict CSP unless AdSense is configured
const { ADS, SITE } = await import(pathToFileURL(path.join(PUB, 'js', 'config.js')).href);
const adsOn = Boolean(ADS.enabled && ADS.client);
const STRICT = "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; font-src 'self' data:; manifest-src 'self'; worker-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'; upgrade-insecure-requests";
// Google's reference AdSense policy relies on per-request nonces; a static site cannot mint those, so we use its
// documented fallback sources. All rendering in this app escapes data, which limits the XSS exposure this adds.
const ADSENSE = "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval' https:; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; connect-src 'self' https:; frame-src https:; font-src 'self' data:; manifest-src 'self'; worker-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'; upgrade-insecure-requests";
const headers = `# Cloudflare Pages headers — generated by scripts/build.mjs (CSP mode: ${adsOn ? 'AdSense enabled' : 'strict, no third-party scripts'})
/*
  Content-Security-Policy: ${adsOn ? ADSENSE : STRICT}
  X-Content-Type-Options: nosniff
  Referrer-Policy: strict-origin-when-cross-origin
  Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=(), usb=(), interest-cohort=()
  X-Frame-Options: SAMEORIGIN
  Cross-Origin-Opener-Policy: same-origin

/index.html
  Cache-Control: no-cache

/sw.js
  Cache-Control: no-cache

/js/*
  Cache-Control: public, max-age=0, must-revalidate

/css/*
  Cache-Control: public, max-age=0, must-revalidate

/icons/*
  Cache-Control: public, max-age=604800
`;
write('_headers', headers);

// 3) sitemap (the app uses hash routes, so the home page is the crawlable entry point)
const base = (SITE.url || 'https://cbt-toolkit.pages.dev').replace(/\/$/, '');
write('sitemap.xml', `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n  <url><loc>${base}/</loc><changefreq>weekly</changefreq><priority>1.0</priority></url>\n</urlset>\n`);
write('robots.txt', `User-agent: *\nAllow: /\nSitemap: ${base}/sitemap.xml\n`);

if (check && stale.length) { console.error(`Generated files are out of date: ${stale.join(', ')}\nRun: npm run build`); process.exit(1); }
console.log(`${check ? 'checked' : 'built'}: ${files.length} files precached · version ${version} · CSP ${adsOn ? 'AdSense' : 'strict'}`);
